Q: How to apply CRUD in laravel A: <p>reports module</p>
<p>controller</p>
<pre><code>use App\Models\{Customer, Order, Product, Payment};
use Illuminate\Support\Facades\DB;

class ReportController extends Controller
{
    public function index()
    {
        // Summary statistics
        $totalCustomers = Customer::count();
        $totalOrders    = Order::count();
        $totalRevenue   = Payment::sum('amount');
        $pendingOrders  = Order::where('status', 'pending')-&gt;count();

        // Top 5 customers by order count
        $topCustomers = Customer::withCount('orders')
            -&gt;orderBy('orders_count', 'desc')
            -&gt;take(5)
            -&gt;get();

        // Monthly sales
        $monthlySales = Order::select(
                DB::raw('MONTH(created_at) as month'),
                DB::raw('SUM(total_amount) as total')
            )
            -&gt;whereYear('created_at', date('Y'))
            -&gt;groupBy('month')
            -&gt;get();

        return view('reports.index', compact(
            'totalCustomers', 'totalOrders',
            'totalRevenue', 'pendingOrders',
            'topCustomers', 'monthlySales'
        ));
    }
}



